mapper.select:
SELECT
    r.*,
    COALESCE(qd.dict_label, r.quality_name) AS quality_name,
    u.real_name as create_user_name,
    d.dept_name as department_name,
    r.rectification_date as rectification_deadline,
    t.task_no as task_no,
    t.task_name as task_name,
    t.inspection_start_time,
    t.inspection_end_time,
    t.publicity_start_time,
    t.publicity_end_time
FROM sys_monthly_inspection_record r
LEFT JOIN sys_user u ON r.create_user_id = u.id
LEFT JOIN sys_dept d ON r.department_id = d.id
LEFT JOIN sys_dictionary qd ON qd.dict_value = r.quality_id AND qd.dict_type = '性质界定' AND qd.deleted = 0
LEFT JOIN sys_monthly_inspection_task t ON r.task_id = t.id
WHERE r.deleted = 0

    AND r.task_id = #{params.taskId}


    AND r.professional_type_id = #{params.professionalTypeId}


    AND r.responsibility_id = #{params.responsibilityId}


    AND r.record_status IN

        #{status}




        AND r.record_status = #{params.recordStatus}



    AND r.rectification_date IS NOT NULL
    AND r.rectification_date  <  #{params.rectificationDeadlineBefore}


    AND r.create_user_id = #{params.createUserId}


    AND r.department_id = #{params.departmentId}


    AND r.check_unit_id = #{params.checkUnitId}


    AND r.responsible_person LIKE CONCAT('%', #{params.responsiblePerson}, '%')


    AND r.inspector LIKE CONCAT('%', #{params.inspector}, '%')


    AND r.create_time  >=  CONCAT(#{params.startDate}, ' 00:00:00')


    AND r.create_time  <=  CONCAT(#{params.endDate}, ' 23:59:59')



    AND (r.create_user_id = #{params.scopeUserId}

        OR u.dept_id = #{params.scopeDeptId}
        OR r.department_id = #{params.scopeDeptId}

    )



    AND t.publicity_start_time IS NOT NULL
    AND t.publicity_start_time  <=  NOW()

ORDER BY r.create_time DESC

SELECT COUNT(*) as total_count, COUNT(CASE WHEN record_status = 0 THEN 1 END) as draft_count, COUNT(CASE WHEN record_status = 1 THEN 1 END) as submitted_count, COUNT(CASE WHEN record_status = 2 THEN 1 END) as audited_count, AVG(safety_score) as avg_safety_score FROM sys_monthly_inspection_record WHERE deleted = 0
AND create_user_id = #{params.createUserId}
AND create_time >= #{params.startDate}
AND create_time <= #{params.endDate}

SELECT DATE_FORMAT(create_time, '%Y-%m') as month, COUNT(*) as count, AVG(safety_score) as avg_score FROM sys_monthly_inspection_record WHERE deleted = 0
AND create_user_id = #{params.createUserId}
AND create_time >= #{params.startDate}
AND create_time <= #{params.endDate}
GROUP BY DATE_FORMAT(create_time, '%Y-%m') ORDER BY month DESC LIMIT 12

SELECT

FROM sys_monthly_inspection_record
WHERE deleted = 0
AND task_id = #{taskId}

    AND record_status = #{recordStatus}

ORDER BY create_time DESC

SELECT

FROM sys_monthly_inspection_record
WHERE deleted = 0
AND create_user_id = #{userId}

    AND record_status = #{recordStatus}

ORDER BY create_time DESC

