UPDATE sys_monthly_inspection_record SET record_status = #{status}, update_time = NOW() WHERE id IN
#{id}
AND deleted = 0

mapper.select:
SELECT d.id as department_id, d.dept_name as department_name, COUNT(r.id) as record_count, COUNT(CASE WHEN r.record_status = 0 THEN 1 END) as draft_count, COUNT(CASE WHEN r.record_status = 1 THEN 1 END) as submitted_count, COUNT(CASE WHEN r.record_status = 2 THEN 1 END) as audited_count, AVG(r.safety_score) as avg_safety_score FROM sys_dept d LEFT JOIN sys_monthly_inspection_record r ON d.id = r.responsibility_id AND r.deleted = 0
AND r.record_status = #{recordStatus}
WHERE d.deleted = 0 GROUP BY d.id, d.dept_name ORDER BY record_count DESC
